 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not out:
        return out

    # The object is a 4-row high bit pattern. Its top row is followed by
    # two rows that spell out an alternating signal in 3-column groups;
    # color the matching tail of that first row with 1.
    # Locate each patterned object by its first non-background row, then
    # fill the empty suffix of the row immediately above the two-row code.
    bg = max(range(10), key=lambda color: sum(cell == color for row in grid for cell in row))
    height, width = len(grid), len(grid[0])
    for r in range(height - 2):
        if any(cell != bg for cell in grid[r]) and all(cell == bg for cell in grid[r - 1]) if r > 0 else False:
            # top edge is row r; color only the trailing blank section
            # where the signal is meant to continue (as demonstrated).
            occupied = [c for c, v in enumerate(grid[r]) if v != bg]
            if occupied:
                # The marked tail is the final run of background cells on the row.
                # It is signaled by a 1-cell gap after the patterned prefix.
                start = max(occupied) + 1
                if start < width:
                    for c in range(start, width):
                        out[r][c] = 1
    return out
