 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))

    # The rows encode a collection of binary words: two copies of the same
    # word (separated vertically) are shown, and the smaller copy is extended
    # with 1 to the width indicated by its counterpart.
    nonempty = [r for r, row in enumerate(grid) if any(v != bg for v in row)]
    if not nonempty:
        return out
    # locate equal-shaped row pairs by their prefix before the trailing blank
    # run. The one that is shorter is the incomplete copy.
    candidates = []
    for r in nonempty:
        xs = [c for c, v in enumerate(grid[r]) if v != bg]
        if xs:
            candidates.append((r, xs[0], xs[-1]))
    # Match rows with similar left edges; for each pair, extend the shorter
    # trailing run only where its later counterpart has foreground.
    for i, (r1, l1, e1) in enumerate(candidates):
        for r2, l2, e2 in candidates[i+1:]:
