    out = [row[:] for row in grid]
    if not grid:
        return out
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    # Blocks of aligned symbols repeat lower in the grid. Extend only the
    # incomplete first row of a block, marking the locations where the next
    # copy's pattern supplies foreground cells.
    bands = []
    r = 0
    while r < len(grid):
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r + 1 < len(grid) and any(v != bg for v in grid[r + 1]):
            r += 1
        bands.append((start, r))
        r += 1
    if len(bands) >= 2:
        # Row patterns correspond cyclically; for each position in the upper
        # repeated pattern, transfer foreground into its empty cells from the
        # corresponding row in the later pattern.
        (a0, a1), (b0, b1) = bands[0], bands[1]
        n = min(a1-a0+1, b1-b0+1)
        for k in range(n):
            ra, rb = a0+k, b0+k
            # Where the later block has a longer row, it determines extension.
            ea = max((c for c,v in enumerate(grid[ra]) if v != bg), default=-1)
            eb = max((c for c,v in enumerate(grid[rb]) if v != bg), default=-1)
            if ea >= 0 and eb > ea:
                for c in range(ea+1, eb+1):
                    if grid[rb][c] != bg:
                        out[ra][c] = 1
            elif eb >= 0 and ea > eb:
                for c in range(eb+1, ea+1):
                    if grid[ra][c] != bg:
                        out[rb][c] = 1
    return out
