 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    h, w = len(grid), len(grid[0])

    # Each nonempty horizontal band is a repeated binary pattern. A short
    # prefix row in a band gets the marker color wherever the next repeated
    # instance has foreground in its right-hand continuation.
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r + 1 < h and any(v != bg for v in grid[r + 1]):
            r += 1
        bands.append((start, r))
        r += 1

    if len(bands) < 2:
        return out

    # Most examples have the two pattern instances adjacent vertically within
    # their respective bands. Compare corresponding relative rows. Extend the
    # shorter row only on cells that match the rightmost pattern in its peer.
    (a0, a1), (b0, b1) = bands[:2]
    for k in range(min(a1 - a0 + 1, b1 - b0 + 1)):
        ra, rb = a0 + k, b0 + k
        xa = [c for c, v in enumerate(grid[ra]) if v != bg]
        xb = [c for c, v in enumerate(grid[rb]) if v != bg]
        if not xa or not xb:
            continue
        ea, eb = max(xa), max(xb)
        if ea < eb:
            for c in range(ea + 1, eb + 1):
                if grid[rb][c] != bg and grid[ra][c] == bg:
                    out[ra][c] = 1
        elif eb < ea:
            for c in range(eb + 1, ea + 1):
                if grid[ra][c] != bg and grid[rb][c] == bg:
                    out[rb][c] = 1

    return out
