        a_cols = [c for c, v in enumerate(grid[ra]) if v != bg]
        b_cols = [c for c, v in enumerate(grid[rb]) if v != bg]
        if not a_cols or not b_cols:
            continue
        # The upper row with the short right edge is the one to complete.
        end_a, end_b = max(a_cols), max(b_cols)
