 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid:
        return out
    bg = max(range(10), key=lambda c: sum(v == c for row in grid for v in row))
    # Pick the densest occupied horizontal band as a tile-pattern template.
    bands = []
    r = 0
    while r < len(grid):
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r + 1 < len(grid) and any(v != bg for v in grid[r + 1]):
            r += 1
        bands.append((start, r))
        r += 1
    if not bands:
        return out
    a, b = max(bands, key=lambda band: sum(v != bg for row in grid[band[0]:band[1]+1] for v in row))
    # Repeat its three-column glyph mask into trailing empty cells of this band.
    # Added pixels are marked 1, existing foreground is left unchanged.
    width = len(grid[0])
    for r in range(a, b + 1):
        for c in range(width):
            if grid[r][c] == bg and c >= 15 and grid[r][c % 3] != bg:
                out[r][c] = 1
    return out
