 "content": "def transform(grid):
    out = [row[:] for row in grid]
    if not grid or not grid[0]:
        return out

    # The two separated four-row drawings are aligned repeats. Extend the
    # lower copy's trailing rows to the rightmost foreground extent of the
    # corresponding row in the upper copy, using marker color 1.
    h, w = len(grid), len(grid[0])
    bg = max(range(10), key=lambda color: sum(v == color for row in grid for v in row))
    bands = []
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r + 1 < h and any(v != bg for v in grid[r + 1]):
            r += 1
        bands.append((start, r))
        r += 1

    if len(bands) >= 2:
        (top, top_end), (bottom, bottom_end) = bands[:2]
        rows = min(top_end - top + 1, bottom_end - bottom + 1)
        for k in range(rows):
            tr, br = top + k, bottom + k
            top_cols = [c for c, v in enumerate(grid[tr]) if v != bg]
            bottom_cols = [c for c, v in enumerate(grid[br]) if v != bg]
            if top_cols and bottom_cols:
                limit = max(top_cols)
                for c in range(max(bottom_cols) + 1, limit + 1):
                    if grid[br][c] == bg:
                        out[br][c] = 1
    return out

